import type { Vec2 } from '../simulation/types';

/**
 * Configuration for the rendering system
 */
export interface RenderConfig {
  /** Padding around the visualization in pixels */
  padding: number;
  /** Background color */
  backgroundColor: string;
  /** Maximum number of trace points to keep */
  maxTracePoints: number;
}

/**
 * Main renderer that manages the canvas and coordinate transformations
 */
export class Renderer {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private config: RenderConfig;

  // Canvas dimensions (logical pixels)
  private width = 0;
  private height = 0;

  // World-to-screen transformation parameters
  private scale = 1;
  private offsetX = 0;
  private offsetY = 0;

  // Reference planet size for zoom calculations (Earth's radius)
  private readonly REFERENCE_PLANET_RADIUS = 6.371e6; // meters

  // Callback to trigger re-render on resize
  private onResize?: () => void;

  constructor(canvas: HTMLCanvasElement, config: RenderConfig) {
    this.canvas = canvas;
    this.config = config;

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Failed to get 2D rendering context');
    }
    this.ctx = ctx;

    // Initial canvas setup
    this.setupCanvas();

    // Set up resize observer to handle container size changes
    this.setupResizeHandler();
  }

  /**
   * Set callback to be called when canvas is resized
   */
  setResizeCallback(callback: () => void): void {
    this.onResize = callback;
  }

  /**
   * Set up canvas for high-DPI rendering
   * Must be called before each render to prevent text/graphic stretching during resize
   */
  private setupCanvas(): void {
    const dpr = window.devicePixelRatio || 1;
    const rect = this.canvas.getBoundingClientRect();

    // Set canvas internal resolution (high DPI)
    this.canvas.width = rect.width * dpr;
    this.canvas.height = rect.height * dpr;

    // Scale context to match
    this.ctx.scale(dpr, dpr);

    // Store logical dimensions
    this.width = rect.width;
    this.height = rect.height;
  }

  /**
   * Set up resize handler using ResizeObserver
   */
  private setupResizeHandler(): void {
    const resizeObserver = new ResizeObserver(() => {
      this.setupCanvas();
      // Trigger re-render callback if set
      if (this.onResize) {
        this.onResize();
      }
    });

    if (this.canvas.parentElement) {
      resizeObserver.observe(this.canvas.parentElement);
    }
  }

  /**
   * Set up coordinate transformation to fit the simulation in view
   * @param _planetRadius Planet radius in meters (world units) - not used for scale calculation
   * @param zoomLevel Zoom multiplier (1.0 = reference planet fits in view, >1 = zoomed in, <1 = zoomed out)
   * @param centerPosition World position to center the view on (e.g., muzzle position)
   */
  setupView(_planetRadius: number, zoomLevel: number, centerPosition: Vec2 = { x: 0, y: 0 }): void {
    // Calculate base scale using REFERENCE planet size (Earth), not actual planet size
    // This ensures zoom is absolute and planet size changes affect apparent display size
    const canvasWidth = this.width - 2 * this.config.padding;
    const canvasHeight = this.height - 2 * this.config.padding;

    // Base scale: reference planet diameter should fit comfortably in the smaller dimension
    const referenceDiameter = this.REFERENCE_PLANET_RADIUS * 2;
    const baseScale = Math.min(canvasWidth, canvasHeight) / referenceDiameter;

    // Apply zoom level to base scale
    this.scale = baseScale * zoomLevel;

    // Center the view on the specified position
    // Convert the center position to screen coordinates, then offset to canvas center
    this.offsetX = this.width / 2 - centerPosition.x * this.scale;
    this.offsetY = this.height / 2 + centerPosition.y * this.scale; // + because y is flipped
  }

  /**
   * Convert world coordinates to screen coordinates
   */
  worldToScreen(worldPos: Vec2): Vec2 {
    return {
      x: worldPos.x * this.scale + this.offsetX,
      y: -worldPos.y * this.scale + this.offsetY // Flip y-axis (screen y grows downward)
    };
  }

  /**
   * Convert world distance to screen distance
   */
  worldToScreenDistance(worldDist: number): number {
    return worldDist * this.scale;
  }

  /**
   * Clear the canvas
   */
  clear(): void {
    // Update canvas resolution before clearing to prevent stretching
    this.setupCanvas();

    this.ctx.fillStyle = this.config.backgroundColor;
    this.ctx.fillRect(0, 0, this.width, this.height);
  }

  /**
   * Get the 2D rendering context
   */
  getContext(): CanvasRenderingContext2D {
    return this.ctx;
  }

  /**
   * Get the current configuration
   */
  getConfig(): RenderConfig {
    return { ...this.config };
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<RenderConfig>): void {
    this.config = { ...this.config, ...config };
  }
}
