import { Simulator } from './simulation/simulator';
import type { SimulationParams, ProjectileState } from './simulation/types';
import { Renderer } from './rendering/renderer';
import type { RenderConfig } from './rendering/renderer';
import { PlanetRenderer } from './rendering/planet';
import { CannonRenderer } from './rendering/cannon';
import { MountainRenderer } from './rendering/mountain';
import { ProjectileRenderer } from './rendering/projectile';
import { AtmosphereRenderer } from './rendering/atmosphere';
import { Controls } from './ui/controls';
import type { SliderConfig } from './ui/controls';
import { calculateOrbitalEccentricity } from './simulation/physics';
import './ui/styles.css';

/**
 * Main application class that coordinathttps://explorables.scienceetonnante.comes simulation, rendering, and UI
 */
class NewtonCannonApp {
  private simulator: Simulator;
  private renderer: Renderer;
  private planetRenderer: PlanetRenderer;
  private cannonRenderer: CannonRenderer;
  private mountainRenderer: MountainRenderer;
  private projectileRenderer: ProjectileRenderer;
  private atmosphereRenderer: AtmosphereRenderer;
  private controls: Controls;

  private animationId: number | null = null;
  private isSimulating = false;
  private statusElement: HTMLElement | null = null;
  private zoomLevel = 1000.0; // Independent zoom control (1.0 = planet fits, >1 = zoomed in)
  private timeAcceleration = 1.0; // Time acceleration multiplier (1x = real time, >1 = faster)

  // Physical constants
  private readonly G = 6.674e-11; // Gravitational constant (m³ kg⁻¹ s⁻²)
  private readonly EARTH_DENSITY = 5514; // Earth's average density (kg/m³)

  /**
   * Calculate planet mass from radius using Earth's average density
   */
  private calculatePlanetMass(radius: number): number {
    const volume = (4 / 3) * Math.PI * Math.pow(radius, 3);
    return this.EARTH_DENSITY * volume;
  }

  constructor(container: HTMLElement) {
    // Create the widget structure
    this.createWidgetStructure(container);

    // Initialize default simulation parameters
    const defaultRadius = 6.371e6; // Earth radius (m) ~6,371 km
    const defaultParams: SimulationParams = {
      planetMass: this.calculatePlanetMass(defaultRadius), // Mass calculated from radius and density
      planetRadius: defaultRadius,
      cannonAltitude: 0,           // Altitude above surface (m)
      launchAngle: Math.PI / 4,    // 45 degrees
      muzzleSpeed: 150,            // 150 m/s (default speed)
      G: this.G,
      dt: 0.1,                     // 0.1 second time step (smaller for accuracy at low speeds)
      escapeBoundMultiplier: 20,   // Show up to 20× planet radius to allow for elliptical orbits
      dragCoefficient: 0,          // Default: no drag
      dragEnabled: true            // Drag always enabled, controlled by coefficient
    };

    // Initialize simulator
    this.simulator = new Simulator(defaultParams);

    // Initialize renderer
    const canvas = container.querySelector('canvas') as HTMLCanvasElement;
    const renderConfig: RenderConfig = {
      padding: 40,
      backgroundColor: '#0a0a1a',
      maxTracePoints: 1000
    };
    this.renderer = new Renderer(canvas, renderConfig);

    // Set up resize callback to update view and re-render
    this.renderer.setResizeCallback(() => {
      this.updateView();
      this.renderScene();
    });

    // Initialize visual components
    this.planetRenderer = new PlanetRenderer({
      fillColor: '#2196F3',
      strokeColor: '#1976D2',
      strokeWidth: 2
    });

    this.mountainRenderer = new MountainRenderer({
      fillColor: '#6B5D4F',
      strokeColor: '#4A3F35',
      strokeWidth: 2,
      angle: 30 // Small acute angle in degrees
    });

    this.cannonRenderer = new CannonRenderer({
      barrelColor: '#5A5A5A',
      barrelWidth: 8,
      barrelLength: 40 // Constant apparent size in screen pixels
    });

    this.projectileRenderer = new ProjectileRenderer(
      {
        projectileColor: '#FFC107',
        projectileRadius: 5,
        traceColor: '#FFC107',
        traceWidth: 3,
        traceAlphaStart: 0.9,
        traceAlphaEnd: 0.1,  // Active comet trail fades
        persistentTraceAlpha: 0.25,  // Persistent trail semi-transparent
        persistentTraceWidth: 1.5  // Thinner line for persistent trail
      },
      renderConfig.maxTracePoints
    );

    this.atmosphereRenderer = new AtmosphereRenderer({
      innerColor: 'rgba(255, 0, 100, 0.45)',  // More opaque yellow at surface
      outerColor: 'rgba(255, 0, 150, 0)',     // Fully transparent at edge
      maxRadiusMultiplier: 5                     // Gradient extends to 5× planet radius
    });

    // Initialize controls
    const controlsContainer = container.querySelector('.controls-container-wrapper') as HTMLElement;
    this.controls = new Controls(controlsContainer);

    const sliderConfigs: SliderConfig[] = [
      {
        id: 'cannon-altitude',
        label: 'Cannon Altitude',
        min: 0,
        max: 1e7,
        step: 1e5,
        defaultValue: defaultParams.cannonAltitude,
        unit: 'km',
        formatter: (v) => (v / 1000).toFixed(0),
        group: 'Launch Parameters'
      },
      {
        id: 'launch-angle',
        label: 'Launch Angle',
        min: 0,
        max: Math.PI / 2,
        step: 0.01,
        defaultValue: defaultParams.launchAngle,
        unit: '°',
        formatter: (v) => ((v * 180) / Math.PI).toFixed(1),
        group: 'Launch Parameters'
      },
      {
        id: 'muzzle-speed',
        label: 'Muzzle Speed',
        min: 150,
        max: 12000,
        step: 50,
        defaultValue: defaultParams.muzzleSpeed,
        unit: 'm/s',
        formatter: (v) => v.toFixed(0),
        group: 'Launch Parameters'
      },
      {
        id: 'drag-coefficient',
        label: 'Viscous Drag Coefficient',
        min: 0,
        max: 5e-6,
        step: 5e-7,
        defaultValue: defaultParams.dragCoefficient,
        unit: '',
        formatter: (v) => v.toExponential(2),
        group: 'Physics'
      },
      {
        id: 'zoom',
        label: 'Zoom',
        min: Math.log10(0.1),      // log10(0.1) = -1
        max: Math.log10(1000),     // log10(1000) = 3
        step: 0.01,                // Small step in log space for smooth control
        defaultValue: Math.log10(this.zoomLevel),
        unit: 'x',
        formatter: (v) => {
          const actualZoom = Math.pow(10, v);
          return actualZoom < 1 ? actualZoom.toFixed(2) : actualZoom.toFixed(1);
        },
        group: 'View Controls'
      },
      {
        id: 'time-acceleration',
        label: 'Time Acceleration',
        min: 1,
        max: 200,
        step: 1,
        defaultValue: this.timeAcceleration,
        unit: 'x',
        formatter: (v) => v.toFixed(0),
        group: 'View Controls'
      }
    ];

    this.controls.createControls(sliderConfigs);

    // Set up event listeners
    this.setupEventListeners();

    // Set up initial view and render
    this.updateView();
    this.renderScene();
  }

  /**
   * Create the HTML structure for the widget
   */
  private createWidgetStructure(container: HTMLElement): void {
    container.innerHTML = `
      <header class="header container">
        <h1 class="header__title">Newton's Cannon</h1>
      </header>

      <main class="container grid-2">
        <section class="panel controls-panel">
          <div class="controls-container-wrapper"></div>
        </section>

        <section class="viz panel">
          <canvas></canvas>
        </section>
      </main>

      <div class="container">
        <div class="status-message"></div>
      </div>
    `;

    this.statusElement = container.querySelector('.status-message');
  }

  /**
   * Set up event listeners for controls
   */
  private setupEventListeners(): void {
    this.controls.on('launch', () => this.launch());
    this.controls.on('reset', () => this.reset());
    this.controls.on('initial', () => this.reset());
    this.controls.on('sliderChange', (id, value) => this.handleSliderChange(id, value));
  }

  /**
   * Handle slider value changes
   */
  private handleSliderChange(id: string, value: number): void {
    const params = this.simulator.getParams();

    // Check if this is a launch parameter (not a view control or physics parameter)
    const isLaunchParameter = ['cannon-altitude', 'launch-angle', 'muzzle-speed'].includes(id);

    // If a launch parameter changes and there's an existing trajectory, clear it
    if (isLaunchParameter && this.projectileRenderer.getTraceLength() > 0) {
      this.projectileRenderer.clearTrace();
      this.simulator.reset();
    }

    if (id === 'cannon-altitude') {
      params.cannonAltitude = value;
      this.simulator.updateParams(params);
      this.updateView();
    } else if (id === 'launch-angle') {
      params.launchAngle = value;
      this.simulator.updateParams(params);
    } else if (id === 'muzzle-speed') {
      params.muzzleSpeed = value;
      this.simulator.updateParams(params);
    } else if (id === 'drag-coefficient') {
      params.dragCoefficient = value;
      params.dragEnabled = value > 0; // Auto-enable drag when coefficient is non-zero
      this.simulator.updateParams(params);
    } else if (id === 'zoom') {
      // Convert from log10 value to actual zoom level
      this.zoomLevel = Math.pow(10, value);
      this.updateView();
    } else if (id === 'time-acceleration') {
      this.timeAcceleration = value;
    }

    // Re-render if not currently simulating
    if (!this.isSimulating) {
      this.renderScene();
    }
  }


  /**
   * Update the view transformation based on current parameters
   */
  private updateView(): void {
    const params = this.simulator.getParams();
    // Center view on the midpoint between cannon and earth surface
    // At altitude 0, this is the surface (planetRadius)
    // At altitude h, this is planetRadius + h/2
    const midpointPosition = {
      x: 0,
      y: params.planetRadius + params.cannonAltitude / 2
    };
    this.renderer.setupView(params.planetRadius, this.zoomLevel, midpointPosition);
  }

  /**
   * Launch the projectile
   */
  private launch(): void {
    if (this.isSimulating) return;

    // Initialize simulation
    this.simulator.initialize();
    this.projectileRenderer.clearTrace();

    // Update UI state
    this.isSimulating = true;
    this.controls.setLaunchEnabled(false);
    // Only disable launch parameter sliders, keep view controls active
    this.controls.setSlidersEnabledByIds(['cannon-altitude', 'launch-angle', 'muzzle-speed'], false);
    this.hideStatus();

    // Start animation loop
    this.animate();
  }

  /**
   * Reset the simulation
   */
  private reset(): void {
    // Stop animation
    if (this.animationId !== null) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }

    // Reset simulator
    this.simulator.reset();
    this.projectileRenderer.clearTrace();

    // Update UI state
    this.isSimulating = false;
    this.controls.setLaunchEnabled(true);
    // Re-enable launch parameter sliders
    this.controls.setSlidersEnabledByIds(['cannon-altitude', 'launch-angle', 'muzzle-speed'], true);
    this.hideStatus();

    // Render initial scene
    this.renderScene();
  }

  /**
   * Main animation loop
   */
  private animate = (): void => {
    if (!this.isSimulating) return;

    // Apply time acceleration by increasing the time step
    const params = this.simulator.getParams();
    const baseDt = 0.1; // Base time step
    const acceleratedDt = baseDt * this.timeAcceleration;

    // Temporarily update dt for this step
    const originalDt = params.dt;
    params.dt = acceleratedDt;
    this.simulator.updateParams(params);

    // Perform fixed number of steps per frame
    const stepsPerFrame = 5;
    let shouldContinue = true;

    for (let i = 0; i < stepsPerFrame && shouldContinue; i++) {
      const result = this.simulator.step();

      // Add trace point
      this.projectileRenderer.addTracePoint(result.state.position, result.state.time);

      // Check if simulation should stop
      if (result.type === 'collided') {
        this.handleCollision();
        shouldContinue = false;
      } else if (result.type === 'escaped') {
        this.handleEscape();
        shouldContinue = false;
      }
    }

    // Restore original dt
    params.dt = originalDt;
    this.simulator.updateParams(params);

    // Render current state
    this.renderScene();

    // Continue animation if still running
    if (this.isSimulating && shouldContinue) {
      this.animationId = requestAnimationFrame(this.animate);
    }
  };

  /**
   * Handle collision with planet surface
   */
  private handleCollision(): void {
    this.isSimulating = false;
    this.controls.setLaunchEnabled(true);
    // Re-enable launch parameter sliders
    this.controls.setSlidersEnabledByIds(['cannon-altitude', 'launch-angle', 'muzzle-speed'], true);
    this.showStatus('Projectile collided with planet surface', 'collided');
  }

  /**
   * Handle escape beyond boundary
   */
  private handleEscape(): void {
    this.isSimulating = false;
    this.controls.setLaunchEnabled(true);
    // Re-enable launch parameter sliders
    this.controls.setSlidersEnabledByIds(['cannon-altitude', 'launch-angle', 'muzzle-speed'], true);
    this.showStatus('Projectile escaped to infinity!', 'escaped');
  }

  /**
   * Render the current scene
   */
  private renderScene(): void {
    const params = this.simulator.getParams();
    const state = this.simulator.getCurrentState();

    // Clear canvas
    this.renderer.clear();

    // Render atmospheric gradient if drag is non-zero
    if (params.dragCoefficient > 0) {
      this.atmosphereRenderer.render(this.renderer, params.planetRadius);
    }

    // Render planet
    this.planetRenderer.render(this.renderer, params.planetRadius);

    // Render mountain (if altitude > 0)
    this.mountainRenderer.render(this.renderer, params.planetRadius, params.cannonAltitude);

    // Render cannon at initial position (top of planet at 90° + altitude)
    const cannonDistance = params.planetRadius + params.cannonAltitude;
    const cannonPosition = {
      x: cannonDistance * Math.cos(Math.PI / 2),
      y: cannonDistance * Math.sin(Math.PI / 2)
    };

    // Calculate cannon scale factor: below zoom 1.0, scale proportionally; above 1.0, keep at 1.0
    const cannonScaleFactor = Math.min(1.0, this.zoomLevel);
    this.cannonRenderer.render(this.renderer, cannonPosition, params.launchAngle, cannonScaleFactor);

    // Render projectile and trace
    this.projectileRenderer.render(this.renderer, state?.position || null);

    // Render scale indicator
    this.renderScaleIndicator();

    // Render eccentricity display if drag is non-zero and projectile is in flight
    if (params.dragCoefficient > 0 && state && this.isSimulating) {
      this.renderEccentricityDisplay(state, params);
    }
  }

  /**
   * Render scale indicator in upper left corner
   */
  private renderScaleIndicator(): void {
    const ctx = this.renderer.getContext();

    // Calculate a nice round scale length in meters
    // The scale bar should be roughly 100-150 pixels long
    const targetPixels = 120;
    const pixelsToMeters = 1 / this.renderer.worldToScreenDistance(1);
    const rawDistance = targetPixels * pixelsToMeters;

    // Round to nice numbers (1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, etc.)
    const magnitude = Math.pow(10, Math.floor(Math.log10(rawDistance)));
    const normalized = rawDistance / magnitude;
    let niceDistance: number;
    if (normalized < 1.5) {
      niceDistance = magnitude;
    } else if (normalized < 3.5) {
      niceDistance = 2 * magnitude;
    } else if (normalized < 7.5) {
      niceDistance = 5 * magnitude;
    } else {
      niceDistance = 10 * magnitude;
    }

    // Convert distance to screen pixels
    const scalePixels = this.renderer.worldToScreenDistance(niceDistance);

    // Format label (show in km if >= 1000m)
    let label: string;
    if (niceDistance >= 1000) {
      label = `${(niceDistance / 1000).toFixed(0)} km`;
    } else {
      label = `${niceDistance.toFixed(0)} m`;
    }

    // Draw scale indicator
    const x = 20;
    const y = 30;
    const lineY = y + 10;

    ctx.save();
    ctx.strokeStyle = 'white';
    ctx.fillStyle = 'white';
    ctx.lineWidth = 2;
    ctx.font = '14px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    ctx.textAlign = 'center'; // Center the text
    ctx.textBaseline = 'bottom';

    // Draw scale line
    ctx.beginPath();
    ctx.moveTo(x, lineY);
    ctx.lineTo(x + scalePixels, lineY);
    ctx.stroke();

    // Draw end ticks
    ctx.beginPath();
    ctx.moveTo(x, lineY - 5);
    ctx.lineTo(x, lineY + 5);
    ctx.moveTo(x + scalePixels, lineY - 5);
    ctx.lineTo(x + scalePixels, lineY + 5);
    ctx.stroke();

    // Draw label centered above the scale, pushed up 3px more
    ctx.fillText(label, x + scalePixels / 2, lineY - 8);

    ctx.restore();
  }

  /**
   * Render instantaneous orbital eccentricity display
   * Shows what the eccentricity would be if drag ceased at this moment
   */
  private renderEccentricityDisplay(state: ProjectileState, params: SimulationParams): void {
    const ctx = this.renderer.getContext();

    // Calculate instantaneous orbital eccentricity
    const eccentricity = calculateOrbitalEccentricity(state.position, state.velocity, params);

    // Position in upper right corner (use logical pixels, not physical canvas dimensions)
    const canvas = ctx.canvas;
    const dpr = window.devicePixelRatio || 1;
    const logicalWidth = canvas.width / dpr;
    const x = logicalWidth - 20;
    const y = 30;

    // Determine color based on orbit type
    let valueColor = 'white';
    if (eccentricity < 0.01) {
      valueColor = '#4CAF50'; // Green - Circular
    } else if (eccentricity < 1.0) {
      valueColor = '#2196F3'; // Blue - Elliptical
    } else if (Math.abs(eccentricity - 1.0) < 0.01) {
      valueColor = '#FF9800'; // Orange - Parabolic
    } else {
      valueColor = '#F44336'; // Red - Hyperbolic
    }

    ctx.save();
    ctx.fillStyle = valueColor;
    ctx.font = 'bold 16px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'top';
    ctx.fillText(`e = ${eccentricity.toFixed(3)}`, x, y);

    ctx.restore();
  }

  /**
   * Show status message
   */
  private showStatus(message: string, type: 'collided' | 'escaped'): void {
    if (this.statusElement) {
      this.statusElement.textContent = message;
      const statusClass = type === 'escaped' ? 'status--success' : 'status--danger';
      this.statusElement.className = `status ${statusClass}`;
      this.statusElement.style.display = 'block';
    }
  }

  /**
   * Hide status message
   */
  private hideStatus(): void {
    if (this.statusElement) {
      this.statusElement.style.display = 'none';
    }
  }
}

// Initialize the app when DOM is ready
function init() {
  const container = document.getElementById('newton-cannon-widget');
  if (!container) {
    console.error('Newton Cannon widget container not found');
    return;
  }

  new NewtonCannonApp(container);
}

// Auto-initialize if DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

// Export for programmatic use
export { NewtonCannonApp };
