import type { Renderer } from './renderer';

/**
 * Visual configuration for the planet
 */
export interface PlanetStyle {
  fillColor: string;
  strokeColor: string;
  strokeWidth: number;
}

/**
 * Renders the planet
 */
export class PlanetRenderer {
  private style: PlanetStyle;

  constructor(style: PlanetStyle) {
    this.style = style;
  }

  /**
   * Render the planet at the origin
   * @param renderer Main renderer instance
   * @param radiusWorld Planet radius in world coordinates
   */
  render(renderer: Renderer, radiusWorld: number): void {
    const ctx = renderer.getContext();
    const center = renderer.worldToScreen({ x: 0, y: 0 });
    const radiusScreen = renderer.worldToScreenDistance(radiusWorld);

    ctx.save();

    // Draw filled circle
    ctx.fillStyle = this.style.fillColor;
    ctx.beginPath();
    ctx.arc(center.x, center.y, radiusScreen, 0, Math.PI * 2);
    ctx.fill();

    // Draw outline
    ctx.strokeStyle = this.style.strokeColor;
    ctx.lineWidth = this.style.strokeWidth;
    ctx.beginPath();
    ctx.arc(center.x, center.y, radiusScreen, 0, Math.PI * 2);
    ctx.stroke();

    ctx.restore();
  }

  /**
   * Update the visual style
   */
  updateStyle(style: Partial<PlanetStyle>): void {
    this.style = { ...this.style, ...style };
  }
}
