import type { ProjectileState, SimulationParams, SimulationStepResult } from './types';
import { calculateAcceleration, Vec2 } from './physics';

/**
 * Velocity-Verlet integrator for symplectic time integration
 *
 * The velocity-Verlet method is a symplectic integrator that conserves energy
 * better than standard Euler or RK methods for Hamiltonian systems like orbits.
 *
 * Algorithm:
 * 1. x(t + dt) = x(t) + v(t) * dt + 0.5 * a(t) * dt²
 * 2. a(t + dt) = calculateAcceleration(x(t + dt))
 * 3. v(t + dt) = v(t) + 0.5 * (a(t) + a(t + dt)) * dt
 */
export class VelocityVerletIntegrator {
  private params: SimulationParams;
  private currentAcceleration: { x: number; y: number };

  constructor(params: SimulationParams, initialState: ProjectileState) {
    this.params = params;
    this.currentAcceleration = calculateAcceleration(
      initialState.position,
      initialState.velocity,
      params
    );
  }

  /**
   * Advance the simulation by one time step
   * @param state Current projectile state
   * @returns Result indicating whether to continue, or if collision/escape occurred
   */
  step(state: ProjectileState): SimulationStepResult {
    const dt = this.params.dt;

    // Step 1: Update position
    // x(t + dt) = x(t) + v(t) * dt + 0.5 * a(t) * dt²
    const newPosition = {
      x: state.position.x + state.velocity.x * dt + 0.5 * this.currentAcceleration.x * dt * dt,
      y: state.position.y + state.velocity.y * dt + 0.5 * this.currentAcceleration.y * dt * dt
    };

    // Step 2: Calculate new velocity (approximate for acceleration calculation)
    // For velocity-dependent forces, we need velocity to calculate acceleration
    // Use semi-implicit approximation: v_temp = v(t) + a(t) * dt
    const tempVelocity = {
      x: state.velocity.x + this.currentAcceleration.x * dt,
      y: state.velocity.y + this.currentAcceleration.y * dt
    };

    // Calculate acceleration at new position with approximate velocity
    const newAcceleration = calculateAcceleration(newPosition, tempVelocity, this.params);

    // Step 3: Update velocity using average of old and new acceleration
    // v(t + dt) = v(t) + 0.5 * (a(t) + a(t + dt)) * dt
    const newVelocity = {
      x: state.velocity.x + 0.5 * (this.currentAcceleration.x + newAcceleration.x) * dt,
      y: state.velocity.y + 0.5 * (this.currentAcceleration.y + newAcceleration.y) * dt
    };

    // Update stored acceleration for next step
    this.currentAcceleration = newAcceleration;

    const newState: ProjectileState = {
      position: newPosition,
      velocity: newVelocity,
      time: state.time + dt
    };

    // Check for collision with planet surface
    const distanceFromCenter = Vec2.magnitude(newPosition);
    if (distanceFromCenter <= this.params.planetRadius) {
      return { type: 'collided', state: newState };
    }

    // Check for escape beyond boundary
    const escapeBound = this.params.planetRadius * this.params.escapeBoundMultiplier;
    if (distanceFromCenter >= escapeBound) {
      return { type: 'escaped', state: newState };
    }

    return { type: 'continue', state: newState };
  }

  /**
   * Update simulation parameters (e.g., if planet size changes)
   */
  updateParams(params: SimulationParams): void {
    this.params = params;
  }
}
