import type { ProjectileState, SimulationParams } from './types';
import { VelocityVerletIntegrator } from './integrator';
import { calculateInitialPosition, calculateInitialVelocity } from './physics';

/**
 * Main simulation controller that manages the physics loop
 */
export class Simulator {
  private params: SimulationParams;
  private integrator: VelocityVerletIntegrator | null = null;
  private currentState: ProjectileState | null = null;

  constructor(params: SimulationParams) {
    this.params = params;
  }

  /**
   * Initialize a new simulation with current parameters
   */
  initialize(): ProjectileState {
    // Calculate initial position on planet rim (at specified altitude)
    const initialPosition = calculateInitialPosition(
      this.params.launchAngle,
      this.params.planetRadius,
      this.params.cannonAltitude
    );

    // Calculate initial velocity based on launch angle and muzzle speed
    const initialVelocity = calculateInitialVelocity(
      this.params.launchAngle,
      this.params.muzzleSpeed,
      initialPosition
    );

    this.currentState = {
      position: initialPosition,
      velocity: initialVelocity,
      time: 0
    };

    // Create new integrator with initial state
    this.integrator = new VelocityVerletIntegrator(this.params, this.currentState);

    return this.currentState;
  }

  /**
   * Advance simulation by one time step
   * @returns Result with new state and status
   */
  step() {
    if (!this.integrator || !this.currentState) {
      throw new Error('Simulation not initialized. Call initialize() first.');
    }

    const result = this.integrator.step(this.currentState);
    this.currentState = result.state;
    return result;
  }

  /**
   * Update simulation parameters
   */
  updateParams(params: Partial<SimulationParams>): void {
    this.params = { ...this.params, ...params };
    if (this.integrator) {
      this.integrator.updateParams(this.params);
    }
  }

  /**
   * Get current simulation parameters
   */
  getParams(): SimulationParams {
    return { ...this.params };
  }

  /**
   * Get current projectile state
   */
  getCurrentState(): ProjectileState | null {
    return this.currentState ? { ...this.currentState } : null;
  }

  /**
   * Reset the simulation
   */
  reset(): void {
    this.currentState = null;
    this.integrator = null;
  }

  /**
   * Check if simulation is initialized
   */
  isInitialized(): boolean {
    return this.integrator !== null && this.currentState !== null;
  }
}
