import type { Renderer } from './renderer';
import type { Vec2 } from '../simulation/types';

/**
 * Visual configuration for the mountain
 */
export interface MountainStyle {
  fillColor: string;
  strokeColor: string;
  strokeWidth: number;
  angle: number; // Acute angle in degrees (angle at the peak)
}

/**
 * Renders a mountain (triangle) below the cannon when altitude > 0
 */
export class MountainRenderer {
  private style: MountainStyle;

  constructor(style: MountainStyle) {
    this.style = style;
  }

  /**
   * Render the mountain at the given position
   * @param renderer Main renderer instance
   * @param planetRadius Planet radius in world units
   * @param altitude Cannon altitude above surface in world units
   */
  render(renderer: Renderer, planetRadius: number, altitude: number): void {
    if (altitude <= 0 || altitude > 2000000) {
      return; // No mountain if cannon is at surface or altitude > 2000 km
    }

    const ctx = renderer.getContext();

    // Peak of the mountain (where cannon is)
    const peakDistance = planetRadius + altitude;
    const peakPosition: Vec2 = {
      x: 0,
      y: peakDistance
    };

    // Convert peak to screen coordinates
    const screenPeak = renderer.worldToScreen(peakPosition);

    // Calculate the base points of the triangle
    // The mountain extends down to the planet surface
    const baseDistance = planetRadius;

    // Calculate half-angle in radians
    const halfAngleRad = (this.style.angle / 2) * (Math.PI / 180);

    // Calculate the horizontal spread at the base
    // Using tan: opposite = altitude, adjacent = half-base-width
    const halfBaseWidth = altitude * Math.tan(halfAngleRad);

    // Base left and right points on the planet surface
    const baseLeft: Vec2 = {
      x: -halfBaseWidth,
      y: baseDistance
    };
    const baseRight: Vec2 = {
      x: halfBaseWidth,
      y: baseDistance
    };

    const screenBaseLeft = renderer.worldToScreen(baseLeft);
    const screenBaseRight = renderer.worldToScreen(baseRight);

    // Draw the mountain triangle
    ctx.save();
    ctx.fillStyle = this.style.fillColor;
    ctx.strokeStyle = this.style.strokeColor;
    ctx.lineWidth = this.style.strokeWidth;

    ctx.beginPath();
    ctx.moveTo(screenPeak.x, screenPeak.y);
    ctx.lineTo(screenBaseLeft.x, screenBaseLeft.y);
    ctx.lineTo(screenBaseRight.x, screenBaseRight.y);
    ctx.closePath();

    ctx.fill();
    ctx.stroke();

    ctx.restore();
  }

  /**
   * Update the visual style
   */
  updateStyle(style: Partial<MountainStyle>): void {
    this.style = { ...this.style, ...style };
  }
}
