import type { Renderer } from './renderer';

/**
 * Visual configuration for the atmosphere
 */
export interface AtmosphereStyle {
  /** Inner color (at planet surface) - semi-transparent yellow */
  innerColor: string;
  /** Outer color (fades to transparent) */
  outerColor: string;
  /** Maximum radius for the gradient as a multiple of planet radius */
  maxRadiusMultiplier: number;
}

/**
 * Renders the atmospheric drag effect as a radial gradient
 */
export class AtmosphereRenderer {
  private style: AtmosphereStyle;

  constructor(style: AtmosphereStyle) {
    this.style = style;
  }

  /**
   * Render the atmospheric gradient around the planet
   * @param renderer Main renderer instance
   * @param planetRadius Planet radius in world coordinates
   */
  render(renderer: Renderer, planetRadius: number): void {
    const ctx = renderer.getContext();
    const center = renderer.worldToScreen({ x: 0, y: 0 });
    const innerRadiusScreen = renderer.worldToScreenDistance(planetRadius);
    const outerRadiusScreen = renderer.worldToScreenDistance(
      planetRadius * this.style.maxRadiusMultiplier
    );

    ctx.save();

    // Create radial gradient from planet surface outward
    const gradient = ctx.createRadialGradient(
      center.x,
      center.y,
      innerRadiusScreen,
      center.x,
      center.y,
      outerRadiusScreen
    );

    // Inner color: semi-transparent yellow at planet surface (more opaque)
    gradient.addColorStop(0, this.style.innerColor);
    // Fade through several stops for smooth transition (denser gradient)
    gradient.addColorStop(0.2, 'rgba(255, 0, 100, 0.35)');
    gradient.addColorStop(0.4, 'rgba(255, 0, 120, 0.25)');
    gradient.addColorStop(0.6, 'rgba(255, 0, 150, 0.15)');
    gradient.addColorStop(0.8, 'rgba(255, 0, 180, 0.08)');
    // Outer color: fully transparent
    gradient.addColorStop(1, this.style.outerColor);

    // Draw the gradient circle
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(center.x, center.y, outerRadiusScreen, 0, Math.PI * 2);
    ctx.fill();

    // Clip out the planet itself so gradient doesn't overlay it
    ctx.globalCompositeOperation = 'destination-out';
    ctx.fillStyle = 'black';
    ctx.beginPath();
    ctx.arc(center.x, center.y, innerRadiusScreen, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  /**
   * Update the visual style
   */
  updateStyle(style: Partial<AtmosphereStyle>): void {
    this.style = { ...this.style, ...style };
  }
}
